import unittest
from unittest.mock import MagicMock, patch
from glados.config import GladosConfig
from glados.llm.cores.vision_client import VisionClient
from glados.system.event_system import EventMessage, EventSystem


class TestVisionClient(unittest.TestCase):

    config = None

    def setUp(self):
        # Mock configuration
        self.config = GladosConfig(
            vision_model="hf.co/second-state/Llava-v1.5-7B-GGUF:latest",
            vision_completion_url="http://localhost:11434/v1",
            completion_url="http://localhost:11434/v1",
            model="foo",
            personality_preprompt=[
                {"system": "You are an assistant."},
                {"user": "Hello!"}
            ],
            api_key="test-api-key",
            wake_word=None,
            wake_word_sensitivity=0.5,
            interruptible=False
        )

        # Create VisionClient instance
        self.vision_client = VisionClient(config=self.config)
        self.vision_client.event_system = MagicMock(spec=EventSystem)

    def test_initialization_with_valid_config(self):
        """Test initialization with valid configuration."""
        self.assertEqual(self.vision_client.model, "hf.co/second-state/Llava-v1.5-7B-GGUF:latest")
        self.assertEqual(self.vision_client.client.base_url, "http://localhost:11434/v1/")

    # def test_initialization_without_model_or_url(self):
    #     """Test that the vision system is disabled without a model or URL."""
    #     self.config.model = None
    #     self.config.vision_model = None
    #     self.config.completion_url = None
    #     self.config.vision_completion_url = None
    #     client = VisionClient(config=self.config)
    #     self.assertIsNone(client.model)
    #     self.assertFalse(hasattr(client, 'client'))

    @patch("threading.Thread.start", MagicMock())  # Prevent thread from starting
    def test_queue_vision_request_with_valid_event(self):
        """Test that a valid vision request is queued."""
        mock_event = EventMessage(content={"file_name": "test_image.png"})
        self.vision_client.queue_vision_request(mock_event)

        with self.vision_client.queue_lock:
            self.assertIn("test_image.png", self.vision_client.image_queue)

    def test_queue_vision_request_without_file_name(self):
        """Test that an event without a file_name is skipped."""
        mock_event = EventMessage(content={})
        self.vision_client.queue_vision_request(mock_event)

        with self.vision_client.queue_lock:
            self.assertEqual(len(self.vision_client.image_queue), 0)

    @patch("threading.Event.wait", MagicMock())  # Prevent infinite loop
    @patch.object(VisionClient, "process_image_request")
    def test_process_image_queue_with_items(self, mock_process_image_request):
        """Test that the process_image_queue method processes items in the queue."""
        mock_event = EventMessage(content={"file_name": "test_image.png", "image_data": "data:image/png;base64,..."})
        with self.vision_client.queue_lock:
            self.vision_client.image_queue["test_image.png"] = mock_event

        # Call the method with stop_after_one=True to process only one item
        self.vision_client.process_image_queue(stop_after_one=True)
        mock_process_image_request.assert_called_once_with("test_image.png", mock_event.content)

    @patch("openai.OpenAI.chat.completions.create")
    def test_process_image_request_calls_openai_api(self, mock_create):
        """Test that process_image_request calls the OpenAI API."""
        mock_create.return_value = MagicMock(choices=[MagicMock(message=MagicMock(content="Test description"))])
        event = EventMessage(
            role="vision",
            name="request",
            content={
                "type": "image_data",
                "image_data": f"data:image/jpeg;base64,",
                "file_name": "file.jpg",
                "room": "living room",
                "description": f"Observing image from xxx",
                "vision_prompt": "identify contents of image relevant for a home assistant automation system, such as "
                                 "dirt, spills or anything that might require triggering robot vacuum cleaner.",
                "additional_prompt": (
                    "automatically trigger the start_vacuuming tool if dirt or spills are identified in the image description "
                    "and if the tool has not already been started. No comment or reply is required for this request"
                ),
            },
            process_output=True,
        )

        self.vision_client.process_image_request("test_image.png", event.content)

        mock_create.assert_called_once()
        self.vision_client.event_system.publish.assert_called_once_with(EventMessage(
            role="vision",
            name="response",
            content={
                "file_name": "test_image.png",
                "description": "Test description",
                "prompt": "Analyze this image."
            }
        ))

    def test_query_vision_model_with_invalid_image_data(self):
        """Test that _query_vision_model raises an error for invalid image data."""
        with self.assertRaises(ValueError):
            self.vision_client._query_vision_model("invalid_data", "Prompt text")


if __name__ == "__main__":
    unittest.main()
